  'method5-para3' => 'Այս մոտեցումը բոլոր ֆայլերը պահում է տեղական՝ առանց վերբեռնման, կարող է պլանավորվել կամ գործարկվել ավտոմատ կերպով և կարող է ինտեգրվել փաստաթղթերի մշակման ավելի մեծ աշխատանքային հոսքերին: ՏՏ մասնագետների, ծրագրավորողների և գրասենյակային ադմինիստրատորների համար, ովքեր զբաղված են փաստաթղթերի մշակման մասշտաբով, դա ամենաարդյունավետ տարբերակն է:',
  'which-method-heading' => 'Ո՞ր մեթոդը պետք է օգտագործեք',
  'which-method-para' => 'Ցանկացած սարքի վրա պատահական առաջադրանք կատարելու համար PDFTools-ի առցանց գործիքը ամենաարագ մեկնարկային կետն է՝ առանց կարգավորում պահանջելու: Օգտատերերի համար, ովքեր նախընտրում են ֆայլերը տեղական պահել, Chrome կամ Acrobat Reader տպման մեթոդն աշխատում է ցանկացած հարթակում: Բարդ կարիքներ ունեցող Mac-ի օգտատերերը նախադիտումը կգտնեն առավել ճկուն: Ծավալի պահանջներ ունեցող մշակողները և օգտվողները պետք է օգտագործեն Python սկրիպտը:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-para1' => 'PDF ֆայլերի բաժանումը չի պահանջում վճարովի ծրագրակազմ կամ տեխնիկական փորձ: Այս ուղեցույցի հինգ մեթոդներն ընդգրկում են յուրաքանչյուր տարածված սցենար՝ արագ միանվագ արդյունահանումից մինչև խմբաքանակի ավտոմատացված մշակում: Մարդկանց մեծամասնության համար առցանց գործիքը կամ բրաուզերի վրա հիմնված տպման մեթոդը խնդիրը լուծում է երկու րոպեից պակաս ժամանակում: Mac-ի օգտատերերն ունեն Preview-ի տեսողական քաշել և թողնել ինտերֆեյսի հավելյալ առավելությունը: Կարևորն իմանալն այն է, որ բաժանումը երբեք չի նվազեցնում որակը, արդյունքը միշտ հավատարիմ է բնօրինակին:',
  'conclusion-para2' => 'Պառակտված բաժինները այլ փաստաթղթերի հետ համատեղելու համար տես միաձուլման PDF գործիքը: Ստացված ֆայլերի չափը նվազեցնելու համար սեղմել PDF գործիքը հասանելի է անվճար PDFTools-ում:',
  'faqs-heading' => 'Հաճախակի տրվող հարցեր',
  'faq1-question' => 'Կարո՞ղ եմ բաժանել գաղտնաբառով պաշտպանված PDF-ը:',
  'faq1-answer' => 'Ոչ առանց ճիշտ գաղտնաբառի: Գործիքներից շատերը ձեզ հուշում են մուտքագրել այն, երբ վերբեռնեք կամ բացեք ֆայլը: Երբ դուք տրամադրում եք ճիշտ գաղտնաբառը, բաժանումը նորմալ է ընթանում: Եթե ​​դուք չունեք գաղտնաբառը, ֆայլը չի ​​կարող բաժանվել, և առանց թույլտվության PDF պաշտպանությունը շրջանցելու փորձն անօրինական է շատ երկրներում:',
  'faq2-question' => 'Արդյո՞ք PDF-ի բաժանումը նվազեցնում է դրա որակը:',
  'faq2-answer' => 'Ոչ: Բաժանումը քաղում է էջերը՝ առանց դրանք վերարտադրելու: Ելքային էջերի բովանդակությունը բայթ մակարդակով նույնական է բնօրինակին: Պատկերի որակը, տեքստի հստակությունը և բոլոր ձևաչափերը ամբողջությամբ պահպանված են:',
  'faq3-question' => 'Կա՞ էջի սահմանափակում PDF ֆայլերը առցանց բաժանելու համար:',
  'faq3-answer' => 'Սահմանափակումները կախված են ծառայությունից: PDFTools-ը մշակում է մինչև մի քանի հարյուր էջ ֆայլեր իր անվճար մակարդակում: Բրաուզերի վրա հիմնված մեթոդների համար, որոնք օգտագործում են Chrome-ը կամ Acrobat Reader-ը, ձեր համակարգչի հասանելի հիշողությունից այն կողմ էջի սահմանափակում չկա:',
  'faq4-question' => 'Կարո՞ղ եմ PDF-ը ավտոմատ կերպով բաժանել առանձին էջերի:',
  'faq4-answer' => 'Այո՛։ PDFTools-ի առցանց գործիքը ներառում է յուրաքանչյուր էջը որպես առանձին ֆայլ հանելու տարբերակ՝ ստեղծելով ZIP արխիվ, որը կարող եք ներբեռնել: Python script մեթոդը կարող է նաև դա անել ավտոմատ կերպով մեծ խմբաքանակների համար:',
  'a' => 'միաձուլել PDF-ը',
  'method1-note2' => 'գործիքը աշխատում է բաժանարարի կողքին՝ փաստաթղթի կառուցվածքի վրա լիարժեք վերահսկողություն ապահովելու համար:',
  'method4-note3' => 'գործիք PDFTools-ում բրաուզերի վրա հիմնված արագ լուծման համար:',
  'conclusion-para3' => 'գործիք. Ստացված ֆայլերի չափը նվազեցնելու համար՝',
  'a2' => 'սեղմել PDF-ը',
